<script setup>
import { computed, nextTick, onBeforeUnmount, onMounted, ref, watch } from 'vue';
import ReviewerPresetFields from './ReviewerPresetFields.vue';
import * as service from '../../services/idpChainService';
const type = ref(new URLSearchParams(location.search).get('type') === 'idp' ? 'idp' : 'eval');
const presets = ref([]), users = ref([]), units = ref([]), loading = ref(true), error = ref(''), toast = ref('');
const search = ref(''), drawer = ref(false), step = ref(1), busy = ref(false), presetId = ref(null), mode = ref('users');
const selectedIds = ref([]), userSearch = ref(''), unitFilter = ref(''), positionFilter = ref(''), unitId = ref(''), includeChildren = ref(false), existingChain = ref('keep');
const unitTargets = ref([]), childUnits = ref([]), descendantCount = ref(0);
const editOpen = ref(false), editingId = ref(null), editError = ref('');
const form = ref({ name: '', description: '', reviewer_ids: [], assignment_user_ids: [], reviewer_pick: '', user_pick: '' });
const membersOpen = ref(false), members = ref([]), membersTitle = ref('');
const title = computed(() => type.value === 'idp' ? 'ลำดับการทำ IDP' : 'ลำดับในการประเมิน');
const selectedPreset = computed(() => presets.value.find(p => p.id === Number(presetId.value)));
const displayedPresets = computed(() => presets.value.filter(p => `${p.name} ${p.description}`.toLowerCase().includes(search.value.trim().toLowerCase())));
const personLabel = id => { const user = users.value.find(user => user.id === Number(id)); return user ? `${user.name} · ${user.position}` : String(id); };
const unitLabel = id => { const unit = units.value.find(unit => unit.id === Number(id)); return unit ? `${unit.parentId ? unitLabel(unit.parentId) + ' / ' : ''}${unit.name}` : '-'; };
const positions = computed(() => [...new Set(users.value.map(user => user.position))]);
const filteredUsers = computed(() => users.value.filter(user => `${user.name} ${user.position} ${unitLabel(user.unitId)}`.toLowerCase().includes(userSearch.value.trim().toLowerCase()) && (!unitFilter.value || user.unitId === Number(unitFilter.value)) && (!positionFilter.value || user.position === positionFilter.value)));
const targets = computed(() => mode.value === 'unit' ? unitTargets.value : users.value.filter(user => selectedIds.value.includes(user.id)));
const existingCount = computed(() => targets.value.filter(user => user.chains[type.value]).length);
const newCount = computed(() => targets.value.length - existingCount.value);
const replacedCount = computed(() => existingChain.value === 'override' ? existingCount.value : 0);
const skippedCount = computed(() => existingChain.value === 'keep' ? existingCount.value : 0);
const actualCount = computed(() => newCount.value + replacedCount.value);
const reviewerOptions = computed(() => users.value.filter(user => !form.value.reviewer_ids.includes(user.id) && !form.value.assignment_user_ids.includes(user.id)).map(user => ({ value: user.id, label: personLabel(user.id) })));
const assignmentOptions = computed(() => reviewerOptions.value);
const refresh = async () => { presets.value = await service.listPresets(type.value); users.value = await service.listUsers(); };
const load = async () => { loading.value = true; error.value = ''; try { await refresh(); units.value = await service.listUnits(); } catch (failure) { error.value = failure.message; } finally { loading.value = false; } };
const changeType = value => { if (drawer.value || editOpen.value) return; type.value = value; search.value = ''; const url = new URL(location.href); url.searchParams.set('type', value); history.replaceState({}, '', url); };
watch(type, load);
let previewSequence = 0;
watch([unitId, includeChildren], async () => { const sequence = ++previewSequence; const preview = await service.previewUnitTargets(unitId.value, includeChildren.value); const all = await service.previewUnitTargets(unitId.value, true); if (sequence !== previewSequence) return; unitTargets.value = preview.users; childUnits.value = preview.childUnits; descendantCount.value = all.childUnits.length; });
let previousFocus = null, oldOverflow = '', toastTimer;
const notify = message => { clearTimeout(toastTimer); toast.value = message; toastTimer = setTimeout(() => { toast.value = ''; }, 5000); };
const overlayOpen = computed(() => drawer.value || editOpen.value || membersOpen.value);
watch(overlayOpen, async open => { if (open) { previousFocus = document.activeElement; oldOverflow = document.body.style.overflow; document.body.style.overflow = 'hidden'; } else { document.body.style.overflow = oldOverflow; previousFocus?.focus(); } });
const focusDialog = async selector => { await nextTick(); document.querySelector(selector)?.focus(); };
const closeDrawer = () => { if (busy.value) return; if ((selectedIds.value.length || unitId.value) && !window.confirm('มีการเลือกค้างอยู่ ต้องการปิดและยกเลิก?')) return; drawer.value = false; };
const openDrawer = preset => { presetId.value = preset.id; step.value = 1; mode.value = 'users'; selectedIds.value = []; userSearch.value = ''; unitFilter.value = ''; positionFilter.value = ''; unitId.value = ''; includeChildren.value = false; existingChain.value = 'keep'; drawer.value = true; void focusDialog('.chain-drawer'); };
const showMembers = (list, heading) => { members.value = list; membersTitle.value = heading; membersOpen.value = true; void focusDialog('.chain-members'); };
const toggleUser = (id, checked) => { selectedIds.value = checked ? [...new Set([...selectedIds.value, id])] : selectedIds.value.filter(value => value !== id); };
const apply = async () => { if (!actualCount.value || busy.value) return; busy.value = true; error.value = ''; try { await service.applyPreset({ type: type.value, presetId: Number(presetId.value), mode: mode.value, ...(mode.value === 'users' ? { userIds: [...selectedIds.value] } : { unitId: Number(unitId.value), includeChildren: includeChildren.value }), existingChain: existingChain.value }); await refresh(); drawer.value = false; notify('บันทึก (ทดสอบ)'); } catch (failure) { error.value = failure.message; } finally { busy.value = false; } };
const openEdit = (preset = null, copy = false) => { if (preset?.system && !copy) return; editingId.value = copy ? null : preset?.id || null; form.value = { name: preset ? `${preset.name}${copy ? ' (สำเนา)' : ''}` : '', description: preset?.description || '', reviewer_ids: [...(preset?.reviewerIds || [])], assignment_user_ids: [], reviewer_pick: '', user_pick: '' }; editError.value = ''; editOpen.value = true; void focusDialog('.chain-editor'); };
const addReviewer = () => { const id = Number(form.value.reviewer_pick); if (id && !form.value.reviewer_ids.includes(id) && !form.value.assignment_user_ids.includes(id)) form.value.reviewer_ids.push(id); form.value.reviewer_pick = ''; };
const addUser = () => { const id = Number(form.value.user_pick); if (id && !form.value.assignment_user_ids.includes(id) && !form.value.reviewer_ids.includes(id)) form.value.assignment_user_ids.push(id); form.value.user_pick = ''; };
const save = async () => { if (busy.value) return; busy.value = true; try { await service.savePreset({ id: editingId.value, type: type.value, name: form.value.name, description: form.value.description, reviewerIds: form.value.reviewer_ids, userIds: form.value.assignment_user_ids }); await refresh(); editOpen.value = false; notify('บันทึก Preset (ทดสอบ)'); } catch (failure) { editError.value = failure.message; } finally { busy.value = false; } };
const remove = async preset => { if (preset.system || !window.confirm(`ลบ “${preset.name}”? ผู้ใช้ที่ได้รับผล ${preset.userCount} คน (ข้อมูลจำลองเท่านั้น)`)) return; try { await service.savePreset({ id: preset.id, type: type.value, remove: true }); await refresh(); notify('ลบ Preset (ทดสอบ)'); } catch (failure) { error.value = failure.message; } };
const closeMembers = () => { membersOpen.value = false; if (drawer.value) void focusDialog('.chain-drawer'); };
const keys = (event, close) => { if (event.key === 'Escape') { event.preventDefault(); event.stopPropagation(); close(); return; } if (event.key !== 'Tab') return; const dialog = event.currentTarget.querySelector('[role="dialog"]') || event.currentTarget; const elements = [...dialog.querySelectorAll('button:not(:disabled), input:not(:disabled), select:not(:disabled), summary, [tabindex="0"]')]; const first = elements[0], last = elements.at(-1); if (event.shiftKey && (document.activeElement === first || document.activeElement === dialog)) { event.preventDefault(); last?.focus(); } else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first?.focus(); } };
onMounted(load);
onBeforeUnmount(() => { clearTimeout(toastTimer); if (overlayOpen.value) document.body.style.overflow = oldOverflow; });
</script>

<template>
  <section class="chain-module">
    <div class="test-banner">โหมดทดสอบ: ข้อมูลจำลอง ยังไม่บันทึกลงระบบ</div>
    <header class="chain-page-head"><h1>ลำดับการประเมิน &amp; IDP</h1><button class="btn btn-p" type="button" @click="openEdit()">{{ type === 'idp' ? '+ สร้างสายอนุมัติ IDP' : '+ สร้างสายผู้ประเมิน' }}</button></header>
    <div class="chain-toolbar"><div class="seg" role="group" aria-label="ประเภทลำดับ"><button v-for="option in [{ key: 'eval', label: 'ลำดับในการประเมิน' }, { key: 'idp', label: 'ลำดับการทำ IDP' }]" :key="option.key" type="button" :class="{ 'is-active': type === option.key }" :aria-pressed="type === option.key" @click="changeType(option.key)">{{ option.label }}</button></div><input v-model="search" class="inp" aria-label="ค้นหา Preset" placeholder="ค้นหาชื่อ / คำอธิบาย Preset" /></div>
    <div v-if="error" role="alert" class="warn-box">{{ error }} <button type="button" class="text-button" @click="load">ลองใหม่</button></div>
    <div v-if="loading" aria-busy="true" aria-label="กำลังโหลดข้อมูลจำลอง" class="skeletons"><div v-for="n in 2" :key="n" class="preset-skeleton"></div></div>
    <div v-else-if="!displayedPresets.length" class="empty-state"><p>ไม่พบ Preset</p><button class="btn btn-s" type="button" @click="openEdit()">{{ type === 'idp' ? '+ สร้างสายอนุมัติ IDP' : '+ สร้างสายผู้ประเมิน' }}</button></div>
    <article v-for="preset in loading ? [] : displayedPresets" :key="preset.id" class="preset-card">
      <div class="preset-copy"><h2>{{ preset.name }} <span v-if="preset.system" class="system-badge">🔒 ระบบกำหนด</span></h2><p>{{ preset.description }}</p><div class="chain" aria-label="ลำดับผู้ประเมิน"><template v-for="(id, index) in preset.reviewerIds" :key="id"><span v-if="index" class="arrow" aria-hidden="true">→</span><span class="step">{{ index + 1 }} · {{ personLabel(id) }}</span></template></div></div>
      <div class="preset-actions"><button class="text-button" type="button" @click="showMembers(users.filter(user => user.chains[type] === preset.id), `ผู้ใช้ ${preset.name}`)">ใช้อยู่ {{ preset.userCount }} คน</button><button class="btn btn-p" type="button" @click="openDrawer(preset)">กำหนดให้ผู้ใช้</button><details><summary aria-label="เมนู Preset">⋯</summary><div class="preset-menu"><button v-if="!preset.system" type="button" @click="openEdit(preset)">✎ แก้ไข</button><button type="button" @click="openEdit(preset, true)">⧉ คัดลอกสายนี้</button><button v-if="!preset.system" type="button" class="danger" @click="remove(preset)">ลบ</button></div></details></div>
    </article>
    <div v-if="toast" class="chain-toast" role="status">✓ {{ toast }}</div>
    <Teleport to="body">
      <div v-if="drawer" class="chain-overlay" @click.self="closeDrawer" @keydown="keys($event, closeDrawer)">
        <section class="chain-drawer" role="dialog" aria-modal="true" aria-labelledby="chain-drawer-title" tabindex="-1" :inert="membersOpen || undefined"><header><div><h2 id="chain-drawer-title">มอบ Preset · {{ title }}</h2><small>ข้อมูลจำลองเท่านั้น</small></div><button type="button" class="close" aria-label="ปิด" @click="closeDrawer">×</button></header>
          <ol class="drawer-stepper"><li v-for="(label, index) in ['Preset', 'กลุ่มเป้าหมาย', 'ยืนยัน']" :key="label" :class="{ current: step === index + 1 }"><b>{{ index + 1 }}</b>{{ label }}</li></ol>
          <div class="drawer-body">
            <template v-if="step === 1"><label class="lbl" for="assign-preset">เลือก Preset</label><select id="assign-preset" v-model="presetId" class="sel"><option v-for="preset in presets" :key="preset.id" :value="preset.id">{{ preset.name }}</option></select><div class="selection-summary"><h3>{{ selectedPreset?.name }}</h3><p>{{ selectedPreset?.description }}</p><div class="chain"><span v-for="(id, index) in selectedPreset?.reviewerIds || []" :key="id" class="step">{{ index + 1 }} · {{ personLabel(id) }}</span></div></div></template>
            <template v-else-if="step === 2">
              <div class="seg"><button type="button" :class="{ 'is-active': mode === 'users' }" @click="mode = 'users'">รายบุคคล</button><button type="button" :class="{ 'is-active': mode === 'unit' }" @click="mode = 'unit'">ทั้งหน่วยงาน</button></div>
              <template v-if="mode === 'users'"><div class="user-filters"><input v-model="userSearch" class="inp" placeholder="ค้นหาชื่อ / ตำแหน่ง / หน่วย" aria-label="ค้นหาผู้ใช้" /><select v-model="unitFilter" class="sel" aria-label="กรองหน่วย"><option value="">ทุกหน่วย</option><option v-for="unit in units" :key="unit.id" :value="unit.id">{{ unitLabel(unit.id) }}</option></select><select v-model="positionFilter" class="sel" aria-label="กรองตำแหน่ง"><option value="">ทุกตำแหน่ง</option><option v-for="position in positions" :key="position">{{ position }}</option></select></div><div class="selection-tools"><button type="button" class="text-button" @click="selectedIds = [...new Set([...selectedIds, ...filteredUsers.map(user => user.id)])]">เลือกทั้งหมดที่แสดง ({{ filteredUsers.length }})</button><button type="button" class="text-button" @click="selectedIds = []">ล้างที่เลือก</button></div><label v-for="user in filteredUsers" :key="user.id" class="target-row"><input type="checkbox" :checked="selectedIds.includes(user.id)" @change="toggleUser(user.id, $event.target.checked)" /><span><strong>{{ user.name }}</strong><small>{{ user.position }} · {{ unitLabel(user.unitId) }}</small><small v-if="user.chains[type]" class="existing-badge">มีสายเดิม: {{ presets.find(p => p.id === user.chains[type])?.name }}</small></span></label><p v-if="!filteredUsers.length" class="empty-state">ไม่พบผู้ใช้ตามตัวกรอง</p></template>
              <template v-else><label class="lbl" for="assign-unit">เลือกหน่วยงาน</label><select id="assign-unit" v-model="unitId" class="sel"><option value="">เลือกหน่วยงาน</option><option v-for="unit in units" :key="unit.id" :value="unit.id">{{ unitLabel(unit.id) }}</option></select><label class="toggle-line"><input v-model="includeChildren" type="checkbox" role="switch" /> รวมหน่วยงานย่อย ({{ descendantCount }} หน่วย)</label><div v-if="unitId" class="selection-summary"><h3>กำลังใช้กับ: {{ unitLabel(unitId) }}</h3><p>ครอบคลุม {{ targets.length }} คน</p><div class="chain"><span v-for="unit in childUnits" :key="unit.id" class="step">{{ unit.name }}</span></div><ul><li v-for="user in targets.slice(0, 5)" :key="user.id">{{ user.name }}</li></ul><button type="button" class="text-button" @click="showMembers(targets, 'ผู้ใช้ที่ครอบคลุม')">ดูทั้งหมด ({{ targets.length }})</button></div><p v-else class="empty-state">เลือกหน่วยงานเพื่อดูตัวอย่างผู้ใช้</p></template>
              <fieldset class="existing-choice"><legend>ผู้ที่มีสายเดิม ({{ existingCount }} คน)</legend><label><input v-model="existingChain" type="radio" value="keep" /> คงสายเดิม ข้ามคนเหล่านี้</label><label><input v-model="existingChain" type="radio" value="override" /> แทนที่ด้วย Preset นี้</label></fieldset>
            </template>
            <template v-else><div class="selection-summary"><h3>{{ selectedPreset?.name }}</h3><p>{{ mode === 'unit' ? unitLabel(unitId) : 'ผู้ใช้ที่เลือกเป็นรายบุคคล' }}</p><p>กลุ่มเป้าหมาย {{ targets.length }} คน</p><dl class="confirmation-counts"><div><dt>เพิ่มใหม่</dt><dd>{{ newCount }}</dd></div><div><dt>แทนที่</dt><dd>{{ replacedCount }}</dd></div><div><dt>ข้าม</dt><dd>{{ skippedCount }}</dd></div></dl></div><div v-if="targets.length > 20 || replacedCount" class="warn-box">{{ targets.length > 20 ? 'มีเป้าหมายมากกว่า 20 คน ' : '' }}{{ replacedCount ? `จะแทนที่สายเดิม ${replacedCount} คน` : '' }} กรุณาตรวจสอบก่อนยืนยัน (ข้อมูลจำลอง)</div><p v-if="!actualCount" class="warn-box">ไม่มีผู้ใช้ที่จะถูกเปลี่ยน เพราะเลือกคงสายเดิมทั้งหมด</p></template>
            <p v-if="error" class="warn-box" role="alert">{{ error }}</p>
          </div>
          <footer><span>เลือกแล้ว {{ targets.length }} คน</span><div><button v-if="step > 1" class="btn btn-s" type="button" :disabled="busy" @click="step--">ย้อนกลับ</button><button v-if="step < 3" class="btn btn-p" type="button" :disabled="step === 1 ? !selectedPreset : !targets.length" @click="step++">ถัดไป</button><button v-else class="btn btn-p" type="button" :disabled="busy || !actualCount" @click="apply">{{ busy ? 'กำลังบันทึก…' : 'ยืนยันมอบ Preset' }}</button></div></footer>
        </section>
      </div>
      <div v-if="editOpen" class="chain-overlay centered" @click.self="editOpen = false" @keydown="keys($event, () => { editOpen = false; })"><section class="chain-editor" role="dialog" aria-modal="true" aria-labelledby="chain-editor-title" tabindex="-1"><header><h2 id="chain-editor-title">{{ editingId ? 'แก้ไข' : 'เพิ่ม' }} {{ title }} (ทดสอบ)</h2><button type="button" class="close" aria-label="ปิด" @click="editOpen = false">×</button></header><div class="drawer-body"><ReviewerPresetFields :hide-user-assignment="true" :assessment-template-form="form" :active-reviewer-template-title="title" :active-reviewer-template-type="type === 'idp' ? 'idp' : 'assessment'" :template-reviewer-options="reviewerOptions" :selected-template-reviewer-ids="form.reviewer_ids" :template-person-label="personLabel" :add-template-reviewer="addReviewer" :remove-template-reviewer="index => form.reviewer_ids.splice(index, 1)" :is-editing-assessment-template="Boolean(editingId)" :template-assignment-user-options="assignmentOptions" :add-template-assignment-user="addUser" :selected-template-user-ids="form.assignment_user_ids" :remove-template-assignment-user="index => form.assignment_user_ids.splice(index, 1)" :assessment-template-error="editError" /></div><footer><button class="btn btn-s" type="button" @click="editOpen = false">ยกเลิก</button><button class="btn btn-p" type="button" :disabled="busy" @click="save">บันทึก (ทดสอบ)</button></footer></section></div>
      <div v-if="membersOpen" class="chain-overlay centered member-overlay" @click.self="closeMembers" @keydown="keys($event, closeMembers)"><section class="chain-members" role="dialog" aria-modal="true" aria-labelledby="chain-members-title" tabindex="-1"><header><h2 id="chain-members-title">{{ membersTitle }} ({{ members.length }})</h2><button class="close" type="button" aria-label="ปิด" @click="closeMembers">×</button></header><div class="drawer-body"><div v-for="user in members" :key="user.id" class="target-row"><span><strong>{{ user.name }}</strong><small>{{ user.position }} · {{ unitLabel(user.unitId) }}</small></span></div><p v-if="!members.length" class="empty-state">ยังไม่มีผู้ใช้</p></div></section></div>
    </Teleport>
  </section>
</template>

<style scoped>
.chain-module{display:grid;gap:18px;font-size:16px;color:var(--color-text)}.test-banner{padding:10px 16px;border-radius:8px;background:#eef6ff;color:#1e4e8c;font-size:14px;text-align:center}.chain-page-head,.chain-toolbar{display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:14px}h1{margin:0;font-size:24px;font-weight:700}h2{margin:0;font-size:18px;font-weight:600}h3{margin:0;font-size:16px}.chain-toolbar>.inp{width:min(360px,100%)}.seg{display:inline-flex;flex-wrap:wrap;padding:4px;background:#f3f0ec;border-radius:10px}.seg button{min-height:40px;padding:8px 18px;border:0;border-radius:8px;background:transparent;font-size:15px;cursor:pointer}.seg button.is-active{background:#fff;box-shadow:0 1px 3px rgb(0 0 0 / .1);color:var(--color-primary);font-weight:600}.preset-card{display:flex;gap:16px;align-items:flex-start;padding:16px 20px;background:#fff;border:1px solid var(--color-border);border-radius:12px;transition:box-shadow .2s ease,border-color .2s ease}.preset-card:hover{border-color:var(--color-primary-border);box-shadow:0 3px 12px rgb(0 0 0 / .06)}.preset-copy{min-width:0;flex:1}.preset-copy p{margin:6px 0;color:#5f6673;font-size:14px}.system-badge{display:inline-flex;margin-left:6px;padding:3px 8px;background:#f3f4f6;color:#5f6673;border-radius:999px;font-size:14px;font-weight:400}.chain{display:flex;flex-wrap:wrap;align-items:center;gap:8px;margin-top:10px}.step{font-size:14px;padding:4px 12px;border-radius:999px;background:#f6f4f1;border:1px solid #e5dfd8;overflow-wrap:anywhere}.arrow{color:#81776d}.preset-actions{display:flex;align-items:center;flex-wrap:wrap;gap:10px}.text-button{min-height:40px;padding:4px 8px;border:0;background:transparent;color:var(--color-primary);font-size:14px;cursor:pointer;text-decoration:underline}.preset-actions details{position:relative}.preset-actions summary{display:grid;place-items:center;min-width:40px;min-height:40px;border:1px solid var(--color-border);border-radius:8px;list-style:none;cursor:pointer}.preset-actions summary::-webkit-details-marker{display:none}.preset-menu{position:absolute;right:0;z-index:5;min-width:150px;padding:4px;border:1px solid var(--color-border);border-radius:8px;background:#fff;box-shadow:0 3px 12px rgb(0 0 0 / .1)}.preset-menu button{display:block;min-height:40px;width:100%;padding:8px 12px;border:0;background:#fff;text-align:left;cursor:pointer;font-size:14px}.preset-menu button:hover{background:var(--color-primary-soft)}.danger{color:#b42318}.empty-state{padding:24px;text-align:center;color:#5f6673;font-size:15px}.preset-skeleton{height:120px;margin-bottom:12px;border-radius:12px;background:linear-gradient(100deg,#f1eeeb,#faf8f6,#f1eeeb)}.chain-toast{position:fixed;bottom:24px;right:24px;z-index:1800;padding:14px 20px;border-radius:10px;background:#e8f5ec;color:#166534;box-shadow:0 4px 18px rgb(0 0 0 / .12)}
